# region: shape
def shape(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: fold
def fold(xs, factor=10):
    return [v * factor for v in xs]

# region: sift
def sift(xs, factor=10):
    return [v * factor for v in xs]

# region: digest
def digest(xs, limit=9):
    return [v if v <= limit else limit for v in xs]

# region: gather
def gather(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) // n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: render
def render(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return render(gather(digest(sift(fold(shape(raw))))))

